def save(path, data):
    with open(path, 'w') as f:
        json.dump(data, f)

def load(path):
    with open(path) as f:
        return json.load(f)

def main():
    state = load(args.state)
    try:
        run(state)
    finally:
        save(args.state, state)

def request(method, url, body=None):
    for delay in (0, .1, .5):
        try:
            return transport(method, url, body)
        except TimeoutError:
            time.sleep(delay)
    raise RetryError(url)

def create_job(spec):
    return request('POST', '/jobs', json.dumps(spec))

def get_job(job_id):
    return request('GET', f'/jobs/{job_id}')

